const version = "14.0.6";
try {
  if (args[0]?.macroPass !== "DamageBonus") return {};
  const target = workflow?.hitTargets?.first();
  if (!target) return {};
  const tactor = target.actor;
  const detailsRace = (tactor?.system?.details?.race ?? "").toString();
  const detailsType = tactor?.system?.details?.type?.value ?? "";
  const raceOrType = `${detailsRace} ${detailsType}`.toLowerCase();
  if (!raceOrType.includes("dragon")) return {};
  const baseTypes = rolledItem?.system?.damage?.base?.types ?? [];
  const dmgType = [...baseTypes][0] ?? "slashing";
  return { damageRoll: `3d6[${dmgType}]`, flavor: "Dragon Slayer bonus damage" };
} catch (err) {
  console.error(`Dragon Slayer Weapon ${version}`, err);
}
